import{_ as a,H as r,f as e,i as t}from"./chunks/framework.Cvt1eIE0.js";const _=JSON.parse('{"title":"第九章 二人の静けさ","description":"","frontmatter":{},"headers":[],"relativePath":"story/6-3.md","filePath":"story/6-3.md"}'),o={name:"story/6-3.md"};function h(i,p,n,s,l,d){return r(),e("div",null,[...p[0]||(p[0]=[t('<h1 id="第九章-二人の静けさ" tabindex="-1">第九章 二人の静けさ <a class="header-anchor" href="#第九章-二人の静けさ" aria-label="Permalink to &quot;第九章 二人の静けさ&quot;">​</a></h1><p>王国歴六十五年。</p><p>スターリンが旅立ってから、三年。</p><p>庭園は相変わらず、朝に花を開かせていた。</p><p>しかし。</p><p>「静かになったね。」</p><p>オーレックスが呟いた。</p><p>「そうだね。」</p><p>ピックバーグは本を閉じた。「うるさい人がいなくなった。」</p><p>二人は少し間を置いてから、笑った。</p><p>笑い始めるのが、一拍遅かった。</p><p>誰かに笑いをつけてもらわなければ、笑い始められないのだと、初めて気づいた。スターリンはいつも、その役割だった。自分でも気づいていなかっただろうが。</p><p>「今頃、向こうでも騒いでるかな。」</p><p>「きっと。天国の門番に怒鳴られてる。」</p><p>「ははは。」</p><p>二人は笑った。</p><p>笑いながら、少しだけ目が潤んだ。</p><p>それも、笑いのうちだった。</p><hr><p>ある夜。</p><p>ピックバーグが、一冊の本を持ってきた。</p><p>「これ。」</p><p>分厚い、手書きの本だった。革表紙に、タイトルがなかった。</p><p>「何、これ。」</p><p>「スターリンへの手紙。」</p><p>オーレックスは目を見開いた。</p><p>「あの男はいつも先に喋るから、こちらが考えている間に話題が変わって、言いそびれることが多かった。だから書いた。生きているうちに言えなかったことを、ずっと書き溜めてた。」</p><p>「……。」</p><p>「お前に読んでほしい。」</p><p>「いいのか？スターリンへの手紙なのに。」</p><p>「お前に読んでほしくて書いたようなものだから。」</p><p>オーレックスは、その本を受け取った。</p><p>重かった。紙の重さではなく、言葉の重さだった。</p><p>その夜。</p><p>月明かりの下で、オーレックスはその本を読んだ。</p><p>笑い飛ばしてきたことへの感謝。不器用だったことへの謝罪。「ありがとう」と言えなかった代わりに書き続けた言葉。</p><p>言いそびれた全部が、何百ページにも渡って書かれていた。</p><p>不器用な、しかし誠実な、研究者の文体で。</p><p>「……馬鹿野郎。」</p><p>オーレックスは呟いた。</p><p>泣きながら。笑いながら。</p><p>「言えばよかったじゃないか。あいつ、絶対喜んだのに。」</p><p>翌朝。</p><p>「読んだ。」</p><p>「……そうか。良かった。」</p><p>二人は庭で紅茶を飲んだ。</p><p>何も言わなかった。</p><p>それで、十分だった。</p><hr><p>スターリンがいなくなってから、不思議なことがあった。</p><p>何か面白いことがあった時。何かに大笑いした時。</p><p>反射的に、横を見てしまう。</p><p>「これ、スターリンが聞いたら笑うだろうな。絶対うるさく反応するやつだ。」</p><p>そう思って、横を見る。いない。</p><p>そのたびに、ほんの一瞬、胸に何かがひっかかる。</p><p>悲しみではない。懐かしさでもない。それより少し温かい、何か。</p><p>「スターリンがいると、笑う頻度が増えていたんだな。」</p><p>ピックバーグが言った。</p><p>「増えてた。あの男は、笑いを作るのが上手だった。意図しないで。」</p><p>「意図しないで、が大事だな。意図してたら、あんなに笑えない。」</p><p>二人は、また笑った。遅い一拍の後で。しかし、確かに、笑った。</p><hr><h1 id="第十章-記録者の遺言" tabindex="-1">第十章 記録者の遺言 <a class="header-anchor" href="#第十章-記録者の遺言" aria-label="Permalink to &quot;第十章 記録者の遺言&quot;">​</a></h1><p>王国歴六十八年。</p><p>秋。</p><p>ピックバーグは、最近よく庭に出た。</p><p>本を持って、ベンチに座って、ゆっくりと読んでいた。</p><p>いつもより、ゆっくりと。</p><p>ページをめくる速度が、少し遅くなっていた。目のせいかもしれなかった。しかし、それだけでもないと、オーレックスには分かった。</p><p>「その本。何を読んでるの。」</p><p>「古代ヴォールト文明の資料だよ。」</p><p>「まだ読んでるの？五十年以上研究して。」</p><p>「まだ分からないことがある。この石材の成分は、現在の技術では再現できない。なぜ何千年経っても崩れないのか。一生かかっても、分からないことがある。それが面白い。」</p><p>「……そういう人だよ、君は。ずっと。」</p><p>「そうだね。ずっと。」</p><p>ピックバーグは本を置いた。</p><p>「ねえ。」</p><p>「ん。」</p><p>「忘れられた砦の冠。あの時の話を、聞かせてくれないか。文献は全部知ってる。記録も全部書いた。でも。君の言葉で聞いたことは、なかった気がして。あの時、冠に触れて、何を感じたか。」</p><p>オーレックスは少し考えた。</p><p>「怖かった。」</p><p>「え？」</p><p>「王様になる気なんて全然なかったから。覚悟がなかった。でも、手が動いた。」</p><p>「なぜ？」</p><p>「……分からない。あの冠が必要としていたんじゃないかな。王様になる人間じゃなくて。誰かのために動ける人間を。」</p><p>「……そうか。」</p><p>ピックバーグは目を閉じた。</p><p>「それで納得した。ずっと気になってたんだ。なぜ冠はお前を選んだのか。力があったからか、賢かったからか。どれも違うと思ってた。」</p><p>「そうだった。誰かのために動ける、という、それだけが理由だった。」</p><p>沈黙。</p><p>「ありがとう。最後に、それを聞けてよかった。」</p><p>「最後って。そんな風に言わないで。」</p><p>「事実を語るのが僕の仕事だよ。」</p><p>「……。」</p><p>「眠くなったら、少し休む。起こさなくていい。」</p><p>「いつもは起こすだろ。」</p><p>「今日は、起こさなくていい。」</p><p>「……分かった。」</p><p>午後の光が、庭園に差し込んでいた。</p><p>ピックバーグは、お気に入りの本を胸に抱いた。</p><p>古代ヴォールト文明の、あの本だった。一生をかけて研究し続けた、あの本だった。</p><p>目を閉じた。</p><p>いつもより静かな、穏やかな表情で。</p><p>呼吸が、ゆっくりになった。</p><p>ゆっくりと。</p><p>静かに。</p><p>「ピックバーグ。」</p><p>しばらくして、オーレックスは呼んだ。</p><p>「……。」</p><p>返事はなかった。</p><p>庭の花が揺れていた。空が、橙色に染まり始めていた。</p><p>オーレックスはその場を離れなかった。</p><p>長い間。ただ、そこにいた。</p><p>やがて静かに言った。</p><p>「スターリンのところへ、行って。」</p><p>「あいつ、きっとまだ騒いでる。止めてやってくれ。」</p><p>「……じゃないと向こうが迷惑だろ。」</p><p>風が吹いた。</p><p>「ありがとう。」</p><p>「親友。」</p><hr><p>翌日の朝。</p><p>オーレックスは一人、庭に出た。</p><p>ベンチに座った。紅茶を飲んだ。</p><p>いつもの席。いつもの時間。</p><p>しかし、隣は、二つとも空いていた。</p><p>「……静かだな。」</p><p>誰もいない庭に、声が吸い込まれた。</p><p>しばらくして、小さく笑った。</p><p>「うるさくなった頭の中で、二人ともまだ喋ってるから。静かにはならないな。」</p><p>花が揺れた。</p><p>光が差した。</p><p>オーレックスは紅茶を、ゆっくりと飲んだ。</p><hr><h1 id="第十一章-永遠の黄金王" tabindex="-1">第十一章 永遠の黄金王 <a class="header-anchor" href="#第十一章-永遠の黄金王" aria-label="Permalink to &quot;第十一章 永遠の黄金王&quot;">​</a></h1><p>王国歴七十五年。</p><p>春。</p><p>九十余歳となったオーレックス。</p><p>白髪の、穏やかな老人。</p><p>しかし。</p><p>その笑顔だけは、若い頃と変わらなかった。</p><p>黄金の牙が、春の光に、今日も静かに輝いていた。</p><hr><p>毎朝、庭に出た。</p><p>紅茶を飲んだ。花を眺めた。</p><p>「今日も来たよ。スターリン。ピックバーグ。」</p><p>誰かに話しかけるように呟いた。返事はなかった。しかし、風が吹くと、花が揺れた。</p><p>それで十分だった。</p><hr><p>孫たちが来ると、オーレックスは何度でも昔話をした。</p><p>「おじいさま！昔のお話聞かせて！」</p><p>「また？」</p><p>「うん！また！」</p><p>「仕方ないな。それじゃ。昔々。まだ僕が王様じゃなかった頃の話。スターリンっていう、世界一うるさい友達がいてね。あと、眼鏡をかけた、世界一賢くて少し皮肉な友達も。」</p><p>リリアが笑った。「本当に。賑やかな人たちでしたね。」</p><p>「最高の親友たちだった。」</p><p>ある日、一人の孫が聞いた。</p><p>「おじいさまは、怖くなかったの？戦争の時。」</p><p>「いつも怖かったよ。」</p><p>「怖かったのに、どうして戦ったの？」</p><p>「誰かが戦わないといけなかったから。それと。スターリンが行くから。ピックバーグが一緒だから。一人じゃ、怖くて無理だったかもしれない。でも、二人がいれば、怖くても動けた。」</p><p>「それが友達の力ってこと？」</p><p>「そうかもしれない。」</p><p>孫は少し考えてから言った。</p><p>「じゃあ、私も友達を大事にする。」</p><p>「……うん。」</p><p>オーレックスは、しっかりと頷いた。</p><p>「それが一番大事なことだよ。」</p><hr><h1 id="第十二章-春の日" tabindex="-1">第十二章 春の日 <a class="header-anchor" href="#第十二章-春の日" aria-label="Permalink to &quot;第十二章 春の日&quot;">​</a></h1><p>王国歴七十五年。</p><p>春の朝。</p><p>庭園に光が差し込んでいた。</p><p>グロウベリーが、今年も実をつけていた。</p><p>押し花の栞を、オーレックスは手のひらに乗せていた。</p><p>もうすっかり色が褪せていた。花弁が何だったかも、分からないほどに。</p><p>しかし、温かみだけは残っていた。</p><p>噴水広場で、夕日に照らされた少女が「また会えますか？」と言った日のことが、鮮やかだった。あの時の空気の温度と、光の色と、水の音だけが、今も鮮やかだった。</p><p>「あなた。」</p><p>リリアが隣に座った。</p><p>「また持ってる。」</p><p>「そりゃ。ずっと持ってるんだから。最初の日から一度も手放したことない。」</p><p>「……知りませんでした。」</p><p>「内緒にしてたから。」</p><p>「今ごろ言うんですか。」</p><p>「今だから言えるんだよ。」</p><p>二人は笑った。</p><p>「幸せでしたか？」</p><p>リリアが尋ねた。静かな声で。</p><p>オーレックスは、ゆっくりと頷いた。</p><p>「うん。」</p><p>「すごく。」</p><p>「戦争も。冒険も。辛いこともあった。失ったものも、たくさんあった。」</p><p>「でも。」</p><p>「全部が。」</p><p>「全部。」</p><p>「幸せだった。」</p><p>「私もです。ありがとう。オーレックスさん。」</p><p>かつて大戦を終わらせた時に、黄金の冠がもたらしてくれた地上の奇跡。ゾンビになる呪いを退けるその光のおかげで、今こうして、リリアと一緒に美しい世界を見上げることができている。</p><p>空が青かった。</p><p>雲がゆっくりと流れていた。</p><p>その時。</p><p>どこかから、懐かしい声が聞こえた気がした。</p><p>『おーい！遅い！』</p><p>『君は本当にマイペースだね。』</p><p>オーレックスは微笑んだ。</p><p>「今行く。」</p><p>「スターリン。ピックバーグ。」</p><p>「もう少しだけ、待っていてくれ。」</p><p>リリアの手を、握った。</p><p>温かかった。</p><p>その温もりの中で、目を閉じた。</p><p>金色の光が、瞼の裏に広がった。</p><p>忘れられた砦の、あの光だった。</p><p>冠の輝きが、見えた。</p><p>そして声が聞こえた。</p><p>遠く、確かに。</p><p>『希望そのものである。』</p><p>そうか、と思った。</p><p>ずっと、これだったのか。</p><p>これが希望だった。</p><p>冠の重さではなく。 戦いの勝利でもなく。</p><p>誰かの手の温もりが。 友の笑い声が。 家族の顔が。</p><p>全部が、希望だった。</p><p>全部が、黄金だった。</p><hr><p>KING PIGLIN I。</p><p>Aurex Goldtusk。</p><p>黄金王。</p><p>世界を救った英雄。</p><p>PIGLIN KINGDOM建国王。</p><p>彼は、愛する人の手を握りながら、静かに目を閉じた。</p><p>その表情は、若い日のように穏やかだった。</p><p>長い旅の末に、ようやく帰ってきたような。</p><p>そんな顔だった。</p><hr><h1 id="終章" tabindex="-1">終章 <a class="header-anchor" href="#終章" aria-label="Permalink to &quot;終章&quot;">​</a></h1><p>数日後。</p><p>王都 GOLDEN BASTION。</p><p>数千万の国民が集まった。</p><p>王国史上最大の国葬。</p><p>鐘が鳴った。花びらが舞った。</p><p>兵士も。子供も。老人も。誰もが涙を流した。</p><p>「ありがとう。陛下。」</p><p>「ありがとう。黄金王。」</p><p>そして。</p><p>アウレル・ゴールドタスクは、父から受け継いだ黄金の冠を、静かに掲げた。</p><p>「父上のような王になります。」</p><p>「民を愛し。」</p><p>「平和を愛し。」</p><p>「希望を守ります。」</p><p>冠は、変わらず、軽かった。</p><p>その軽さが、何を意味するか。</p><p>アウレルには、もう、分かっていた。</p><p>時代は進む。</p><p>人は変わる。</p><p>王も変わる。</p><p>それでも。</p><p>受け継がれていくものはある。</p><p>友情。</p><p>家族。</p><p>愛。</p><p>そして。</p><p>希望。</p><hr><p>PIGLIN KING</p><p>第六巻 永遠の黄金王</p><p>完</p>',268)])])}const u=a(o,[["render",h]]);export{_ as __pageData,u as default};
